// PurchaseOrderServiceClient is the client API for PurchaseOrderService service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
//
// PurchaseOrderService turns requirements into orders placed with suppliers.
//
// Consolidation is the point: three contracts each short 500 become one order
// for 1500, which is the only way a buyer gets a better price. So an order
// references requirements, and a requirement may span several orders.
type PurchaseOrderServiceClient interface {
	// 死信运维口：列出被放弃的事件、把一条事件重新跑一遍。
	// 平台运维专用（网关按平台操作员名单守门），不属于任何一家公司的业务面。
	ListFailedEvents(ctx context.Context, in *ListFailedEventsRequest, opts ...grpc.CallOption) (*ListFailedEventsResponse, error)
	ReplayFailedEvent(ctx context.Context, in *ReplayFailedEventRequest, opts ...grpc.CallOption) (*ReplayFailedEventResponse, error)
	ListOrders(ctx context.Context, in *ListOrdersRequest, opts ...grpc.CallOption) (*ListOrdersResponse, error)
	GetOrder(ctx context.Context, in *GetOrderRequest, opts ...grpc.CallOption) (*GetOrderResponse, error)
	// Preview persists the rows the employee reviewed but does not allocate a
	// purchase-order number or change a requirement.
	PreviewOrderImport(ctx context.Context, in *PreviewOrderImportRequest, opts ...grpc.CallOption) (*PreviewOrderImportResponse, error)
	// Parse the system purchase template, validate its protected identities and
	// create one ordinary import session per supplier.
	PreviewPurchaseTemplateImport(ctx context.Context, in *PreviewPurchaseTemplateImportRequest, opts ...grpc.CallOption) (*PreviewPurchaseTemplateImportResponse, error)
	// Confirmation is idempotent by import_token. The import record and draft
	// order are committed together.
	ConfirmOrderImport(ctx context.Context, in *ConfirmOrderImportRequest, opts ...grpc.CallOption) (*ConfirmOrderImportResponse, error)
	CreateOrder(ctx context.Context, in *CreateOrderRequest, opts ...grpc.CallOption) (*CreateOrderResponse, error)
	// Only a draft or a rejected order can be changed. Saving a rejected order
	// turns it back into a draft so its corrected snapshot is explicit before
	// it enters a new approval instance.
	UpdateOrder(ctx context.Context, in *UpdateOrderRequest, opts ...grpc.CallOption) (*UpdateOrderResponse, error)
	// Spending money needs a signature. The approval engine routes on the
	// order total, so a large order can require more of them.
	SubmitOrder(ctx context.Context, in *SubmitOrderRequest, opts ...grpc.CallOption) (*SubmitOrderResponse, error)
	CancelOrder(ctx context.Context, in *CancelOrderRequest, opts ...grpc.CallOption) (*CancelOrderResponse, error)
	// Finished goods arriving into a port-terminal custody location.
	ReceiveOrder(ctx context.Context, in *ReceiveOrderRequest, opts ...grpc.CallOption) (*ReceiveOrderResponse, error)
	GetOrderDocuments(ctx context.Context, in *GetOrderDocumentsRequest, opts ...grpc.CallOption) (*GetOrderDocumentsResponse, error)
	BeginOrderSend(ctx context.Context, in *BeginOrderSendRequest, opts ...grpc.CallOption) (*BeginOrderSendResponse, error)
	CompleteOrderSend(ctx context.Context, in *CompleteOrderSendRequest, opts ...grpc.CallOption) (*CompleteOrderSendResponse, error)
	GetOrderExecution(ctx context.Context, in *GetOrderExecutionRequest, opts ...grpc.CallOption) (*GetOrderExecutionResponse, error)
	RecordSupplierConfirmation(ctx context.Context, in *RecordSupplierConfirmationRequest, opts ...grpc.CallOption) (*RecordSupplierConfirmationResponse, error)
	SaveProductionMilestone(ctx context.Context, in *SaveProductionMilestoneRequest, opts ...grpc.CallOption) (*SaveProductionMilestoneResponse, error)
	ReportReceiptException(ctx context.Context, in *ReportReceiptExceptionRequest, opts ...grpc.CallOption) (*ReportReceiptExceptionResponse, error)
	ResolveReceiptException(ctx context.Context, in *ResolveReceiptExceptionRequest, opts ...grpc.CallOption) (*ResolveReceiptExceptionResponse, error)
	// 质检记录（A3）：结果、不合格数量、附件、处置。挂在收货单上。
	RecordInspection(ctx context.Context, in *RecordInspectionRequest, opts ...grpc.CallOption) (*RecordInspectionResponse, error)
	ResolveInspection(ctx context.Context, in *ResolveInspectionRequest, opts ...grpc.CallOption) (*ResolveInspectionResponse, error)
	// 结案：全部收满、无未解决异常、无未解决质检才放行。
	CloseOrder(ctx context.Context, in *CloseOrderRequest, opts ...grpc.CallOption) (*CloseOrderResponse, error)
	// Supplier invoices: the third leg of the three-way match. Lives on the
	// order service because an invoice is meaningless except against orders.
	CreateSupplierInvoice(ctx context.Context, in *CreateSupplierInvoiceRequest, opts ...grpc.CallOption) (*CreateSupplierInvoiceResponse, error)
	ListSupplierInvoices(ctx context.Context, in *ListSupplierInvoicesRequest, opts ...grpc.CallOption) (*ListSupplierInvoicesResponse, error)
	GetSupplierInvoice(ctx context.Context, in *GetSupplierInvoiceRequest, opts ...grpc.CallOption) (*GetSupplierInvoiceResponse, error)
	VoidSupplierInvoice(ctx context.Context, in *VoidSupplierInvoiceRequest, opts ...grpc.CallOption) (*VoidSupplierInvoiceResponse, error)
	// Re-runs the three-way verdict — after a receipt lands or an exception
	// is resolved, the stored MATCHED/EXCEPTION may be stale.
	MatchSupplierInvoice(ctx context.Context, in *MatchSupplierInvoiceRequest, opts ...grpc.CallOption) (*MatchSupplierInvoiceResponse, error)
	// The scan of the paper. Presign hands the browser a short-lived URL it
	// PUTs the file to; Attach records the uploaded key on the invoice. The
	// download URL is minted fresh on every Get — the URL expires, the key
	// does not.
	PresignSupplierInvoiceFile(ctx context.Context, in *PresignSupplierInvoiceFileRequest, opts ...grpc.CallOption) (*PresignSupplierInvoiceFileResponse, error)
	AttachSupplierInvoiceFile(ctx context.Context, in *AttachSupplierInvoiceFileRequest, opts ...grpc.CallOption) (*AttachSupplierInvoiceFileResponse, error)
	// Payments: our assertion that money left. Allocation is the separate,
	// revisable judgement about what it settled — an invoice, or a purchase
	// order when it is a deposit wired before any invoice exists.
	CreateSupplierPayment(ctx context.Context, in *CreateSupplierPaymentRequest, opts ...grpc.CallOption) (*CreateSupplierPaymentResponse, error)
	ListSupplierPayments(ctx context.Context, in *ListSupplierPaymentsRequest, opts ...grpc.CallOption) (*ListSupplierPaymentsResponse, error)
	GetSupplierPayment(ctx context.Context, in *GetSupplierPaymentRequest, opts ...grpc.CallOption) (*GetSupplierPaymentResponse, error)
	AllocateSupplierPayment(ctx context.Context, in *AllocateSupplierPaymentRequest, opts ...grpc.CallOption) (*AllocateSupplierPaymentResponse, error)
	ReverseSupplierPaymentAllocation(ctx context.Context, in *ReverseSupplierPaymentAllocationRequest, opts ...grpc.CallOption) (*ReverseSupplierPaymentAllocationResponse, error)
	// The reconciliation view (A4 P5): one row per supplier and currency,
	// summing all five kinds of paper. Read-only — every number here is
	// derived from the tables above and never stored.
	ListSupplierStatements(ctx context.Context, in *ListSupplierStatementsRequest, opts ...grpc.CallOption) (*ListSupplierStatementsResponse, error)
	GetSupplierStatement(ctx context.Context, in *GetSupplierStatementRequest, opts ...grpc.CallOption) (*GetSupplierStatementResponse, error)
	// Supplier reconciliation, done by hand: one row per purchase order, the
	// amounts typed in by whoever is doing the reconciling, and "is this
	// settled" answered by a person rather than by arithmetic. Nothing here
	// reads an invoice or a bank row — invoices are evidence to attach, and
	// bank rows are a record of their own.
	ListSupplierRecon(ctx context.Context, in *ListSupplierReconRequest, opts ...grpc.CallOption) (*ListSupplierReconResponse, error)
	ListPurchaseOrderPayments(ctx context.Context, in *ListPurchaseOrderPaymentsRequest, opts ...grpc.CallOption) (*ListPurchaseOrderPaymentsResponse, error)
	RecordPurchaseOrderPayment(ctx context.Context, in *RecordPurchaseOrderPaymentRequest, opts ...grpc.CallOption) (*RecordPurchaseOrderPaymentResponse, error)
	ReversePurchaseOrderPayment(ctx context.Context, in *ReversePurchaseOrderPaymentRequest, opts ...grpc.CallOption) (*ReversePurchaseOrderPaymentResponse, error)
	ClosePurchaseOrderPayment(ctx context.Context, in *ClosePurchaseOrderPaymentRequest, opts ...grpc.CallOption) (*ClosePurchaseOrderPaymentResponse, error)
	ReopenPurchaseOrderPayment(ctx context.Context, in *ReopenPurchaseOrderPaymentRequest, opts ...grpc.CallOption) (*ReopenPurchaseOrderPaymentResponse, error)
	// 给存量采购单补应付到期日。到期日是从「配了账期之后下的单」才开始
	// 写入的，在此之前的单一张都没有——不补一次，上线第一天整页都是
	// 「未配账期」。按供应商当前配的账期算，幂等，跑几遍结果一样。
	BackfillPayableDue(ctx context.Context, in *BackfillPayableDueRequest, opts ...grpc.CallOption) (*BackfillPayableDueResponse, error)
	// 挂在一张采购单上的凭证——发票扫描件、水单、退款回执。存的是**纸**，
	// 不是有金额、有明细、参与运算的单据：它不进任何求和，只是「这笔钱是
	// 怎么回事」的证据。一张单可以有好几份。
	PresignReconFile(ctx context.Context, in *PresignReconFileRequest, opts ...grpc.CallOption) (*PresignReconFileResponse, error)
	AttachReconFile(ctx context.Context, in *AttachReconFileRequest, opts ...grpc.CallOption) (*AttachReconFileResponse, error)
	ListReconFiles(ctx context.Context, in *ListReconFilesRequest, opts ...grpc.CallOption) (*ListReconFilesResponse, error)
	RemoveReconFile(ctx context.Context, in *RemoveReconFileRequest, opts ...grpc.CallOption) (*RemoveReconFileResponse, error)
	// Bank statement rows: the fifth voice. Imported verbatim from the CSV
	// the bank portal exports, deduplicated by the bank's own reference, and
	// matched to payments — the match lives on the payment and is reversible;
	// the bank's row never changes.
	ImportBankStatement(ctx context.Context, in *ImportBankStatementRequest, opts ...grpc.CallOption) (*ImportBankStatementResponse, error)
	ListBankTransactions(ctx context.Context, in *ListBankTransactionsRequest, opts ...grpc.CallOption) (*ListBankTransactionsResponse, error)
	MatchBankTransaction(ctx context.Context, in *MatchBankTransactionRequest, opts ...grpc.CallOption) (*MatchBankTransactionResponse, error)
	// 记下这笔钱是谁那条线上的（客户 / 供应商 / 退税 / 不用核销 / 待处理）。
	// 银行那一行本身一个字不改——归属是我们的判断，可改可撤。
	SetBankTransactionOwnership(ctx context.Context, in *SetBankTransactionOwnershipRequest, opts ...grpc.CallOption) (*SetBankTransactionOwnershipResponse, error)
	UnmatchBankTransaction(ctx context.Context, in *UnmatchBankTransactionRequest, opts ...grpc.CallOption) (*UnmatchBankTransactionResponse, error)
	// 手工登记一行流水。CSV 导入之外的另一条入口：银行还没出对账单、或者
	// 客户先发了水单，财务要先把这笔钱记下来。出口的收款对账原来自己有一张
	// 表干这件事，F2 之后由这里统一收着。
	RecordBankTransaction(ctx context.Context, in *RecordBankTransactionRequest, opts ...grpc.CallOption) (*RecordBankTransactionResponse, error)
	// 银行给的那份对账单（PDF）。流水行是员工敲进来的数，对账单是凭证——
	// 两者对不上时说了算的是纸。一行一份，再传一次是替换。
	PresignBankTransactionFile(ctx context.Context, in *PresignBankTransactionFileRequest, opts ...grpc.CallOption) (*PresignBankTransactionFileResponse, error)
	AttachBankTransactionFile(ctx context.Context, in *AttachBankTransactionFileRequest, opts ...grpc.CallOption) (*AttachBankTransactionFileResponse, error)
	// 取单独一行。核销之前要拿到金额和币种才能判断能不能核，靠它。
	GetBankTransaction(ctx context.Context, in *GetBankTransactionRequest, opts ...grpc.CallOption) (*GetBankTransactionResponse, error)
	// 我们自己的银行账户。跟着账本走：账本在这个服务里，账户清单也在这里，
	// 否则流水上的 account_id 指不到任何地方。
	ListBankAccounts(ctx context.Context, in *ListBankAccountsRequest, opts ...grpc.CallOption) (*ListBankAccountsResponse, error)
	CreateBankAccount(ctx context.Context, in *CreateBankAccountRequest, opts ...grpc.CallOption) (*CreateBankAccountResponse, error)
	// 记下这一行被认领了多少。客户那条线的核销记录在出口库，出口核完之后把
	// 结果写回来——账本自己算不出来，但账本必须知道，否则「还没处理完」那个
	// 队列就筛不准。
	SetBankTransactionClaim(ctx context.Context, in *SetBankTransactionClaimRequest, opts ...grpc.CallOption) (*SetBankTransactionClaimResponse, error)
}

