// PurchaseOrderServiceServer is the server API for PurchaseOrderService service.
// All implementations must embed UnimplementedPurchaseOrderServiceServer
// for forward compatibility.
//
// PurchaseOrderService turns requirements into orders placed with suppliers.
//
// Consolidation is the point: three contracts each short 500 become one order
// for 1500, which is the only way a buyer gets a better price. So an order
// references requirements, and a requirement may span several orders.
type PurchaseOrderServiceServer interface {
	// 死信运维口：列出被放弃的事件、把一条事件重新跑一遍。
	// 平台运维专用（网关按平台操作员名单守门），不属于任何一家公司的业务面。
	ListFailedEvents(context.Context, *ListFailedEventsRequest) (*ListFailedEventsResponse, error)
	ReplayFailedEvent(context.Context, *ReplayFailedEventRequest) (*ReplayFailedEventResponse, error)
	ListOrders(context.Context, *ListOrdersRequest) (*ListOrdersResponse, error)
	GetOrder(context.Context, *GetOrderRequest) (*GetOrderResponse, error)
	// Preview persists the rows the employee reviewed but does not allocate a
	// purchase-order number or change a requirement.
	PreviewOrderImport(context.Context, *PreviewOrderImportRequest) (*PreviewOrderImportResponse, error)
	// Parse the system purchase template, validate its protected identities and
	// create one ordinary import session per supplier.
	PreviewPurchaseTemplateImport(context.Context, *PreviewPurchaseTemplateImportRequest) (*PreviewPurchaseTemplateImportResponse, error)
	// Confirmation is idempotent by import_token. The import record and draft
	// order are committed together.
	ConfirmOrderImport(context.Context, *ConfirmOrderImportRequest) (*ConfirmOrderImportResponse, error)
	CreateOrder(context.Context, *CreateOrderRequest) (*CreateOrderResponse, error)
	// Only a draft or a rejected order can be changed. Saving a rejected order
	// turns it back into a draft so its corrected snapshot is explicit before
	// it enters a new approval instance.
	UpdateOrder(context.Context, *UpdateOrderRequest) (*UpdateOrderResponse, error)
	// Spending money needs a signature. The approval engine routes on the
	// order total, so a large order can require more of them.
	SubmitOrder(context.Context, *SubmitOrderRequest) (*SubmitOrderResponse, error)
	CancelOrder(context.Context, *CancelOrderRequest) (*CancelOrderResponse, error)
	// Finished goods arriving into a port-terminal custody location.
	ReceiveOrder(context.Context, *ReceiveOrderRequest) (*ReceiveOrderResponse, error)
	GetOrderDocuments(context.Context, *GetOrderDocumentsRequest) (*GetOrderDocumentsResponse, error)
	BeginOrderSend(context.Context, *BeginOrderSendRequest) (*BeginOrderSendResponse, error)
	CompleteOrderSend(context.Context, *CompleteOrderSendRequest) (*CompleteOrderSendResponse, error)
	GetOrderExecution(context.Context, *GetOrderExecutionRequest) (*GetOrderExecutionResponse, error)
	RecordSupplierConfirmation(context.Context, *RecordSupplierConfirmationRequest) (*RecordSupplierConfirmationResponse, error)
	SaveProductionMilestone(context.Context, *SaveProductionMilestoneRequest) (*SaveProductionMilestoneResponse, error)
	ReportReceiptException(context.Context, *ReportReceiptExceptionRequest) (*ReportReceiptExceptionResponse, error)
	ResolveReceiptException(context.Context, *ResolveReceiptExceptionRequest) (*ResolveReceiptExceptionResponse, error)
	// 质检记录（A3）：结果、不合格数量、附件、处置。挂在收货单上。
	RecordInspection(context.Context, *RecordInspectionRequest) (*RecordInspectionResponse, error)
	ResolveInspection(context.Context, *ResolveInspectionRequest) (*ResolveInspectionResponse, error)
	// 结案：全部收满、无未解决异常、无未解决质检才放行。
	CloseOrder(context.Context, *CloseOrderRequest) (*CloseOrderResponse, error)
	// Supplier invoices: the third leg of the three-way match. Lives on the
	// order service because an invoice is meaningless except against orders.
	CreateSupplierInvoice(context.Context, *CreateSupplierInvoiceRequest) (*CreateSupplierInvoiceResponse, error)
	ListSupplierInvoices(context.Context, *ListSupplierInvoicesRequest) (*ListSupplierInvoicesResponse, error)
	GetSupplierInvoice(context.Context, *GetSupplierInvoiceRequest) (*GetSupplierInvoiceResponse, error)
	VoidSupplierInvoice(context.Context, *VoidSupplierInvoiceRequest) (*VoidSupplierInvoiceResponse, error)
	// Re-runs the three-way verdict — after a receipt lands or an exception
	// is resolved, the stored MATCHED/EXCEPTION may be stale.
	MatchSupplierInvoice(context.Context, *MatchSupplierInvoiceRequest) (*MatchSupplierInvoiceResponse, error)
	// The scan of the paper. Presign hands the browser a short-lived URL it
	// PUTs the file to; Attach records the uploaded key on the invoice. The
	// download URL is minted fresh on every Get — the URL expires, the key
	// does not.
	PresignSupplierInvoiceFile(context.Context, *PresignSupplierInvoiceFileRequest) (*PresignSupplierInvoiceFileResponse, error)
	AttachSupplierInvoiceFile(context.Context, *AttachSupplierInvoiceFileRequest) (*AttachSupplierInvoiceFileResponse, error)
	// Payments: our assertion that money left. Allocation is the separate,
	// revisable judgement about what it settled — an invoice, or a purchase
	// order when it is a deposit wired before any invoice exists.
	CreateSupplierPayment(context.Context, *CreateSupplierPaymentRequest) (*CreateSupplierPaymentResponse, error)
	ListSupplierPayments(context.Context, *ListSupplierPaymentsRequest) (*ListSupplierPaymentsResponse, error)
	GetSupplierPayment(context.Context, *GetSupplierPaymentRequest) (*GetSupplierPaymentResponse, error)
	AllocateSupplierPayment(context.Context, *AllocateSupplierPaymentRequest) (*AllocateSupplierPaymentResponse, error)
	ReverseSupplierPaymentAllocation(context.Context, *ReverseSupplierPaymentAllocationRequest) (*ReverseSupplierPaymentAllocationResponse, error)
	// The reconciliation view (A4 P5): one row per supplier and currency,
	// summing all five kinds of paper. Read-only — every number here is
	// derived from the tables above and never stored.
	ListSupplierStatements(context.Context, *ListSupplierStatementsRequest) (*ListSupplierStatementsResponse, error)
	GetSupplierStatement(context.Context, *GetSupplierStatementRequest) (*GetSupplierStatementResponse, error)
	// Supplier reconciliation, done by hand: one row per purchase order, the
	// amounts typed in by whoever is doing the reconciling, and "is this
	// settled" answered by a person rather than by arithmetic. Nothing here
	// reads an invoice or a bank row — invoices are evidence to attach, and
	// bank rows are a record of their own.
	ListSupplierRecon(context.Context, *ListSupplierReconRequest) (*ListSupplierReconResponse, error)
	ListPurchaseOrderPayments(context.Context, *ListPurchaseOrderPaymentsRequest) (*ListPurchaseOrderPaymentsResponse, error)
	RecordPurchaseOrderPayment(context.Context, *RecordPurchaseOrderPaymentRequest) (*RecordPurchaseOrderPaymentResponse, error)
	ReversePurchaseOrderPayment(context.Context, *ReversePurchaseOrderPaymentRequest) (*ReversePurchaseOrderPaymentResponse, error)
	ClosePurchaseOrderPayment(context.Context, *ClosePurchaseOrderPaymentRequest) (*ClosePurchaseOrderPaymentResponse, error)
	ReopenPurchaseOrderPayment(context.Context, *ReopenPurchaseOrderPaymentRequest) (*ReopenPurchaseOrderPaymentResponse, error)
	// 给存量采购单补应付到期日。到期日是从「配了账期之后下的单」才开始
	// 写入的，在此之前的单一张都没有——不补一次，上线第一天整页都是
	// 「未配账期」。按供应商当前配的账期算，幂等，跑几遍结果一样。
	BackfillPayableDue(context.Context, *BackfillPayableDueRequest) (*BackfillPayableDueResponse, error)
	// 挂在一张采购单上的凭证——发票扫描件、水单、退款回执。存的是**纸**，
	// 不是有金额、有明细、参与运算的单据：它不进任何求和，只是「这笔钱是
	// 怎么回事」的证据。一张单可以有好几份。
	PresignReconFile(context.Context, *PresignReconFileRequest) (*PresignReconFileResponse, error)
	AttachReconFile(context.Context, *AttachReconFileRequest) (*AttachReconFileResponse, error)
	ListReconFiles(context.Context, *ListReconFilesRequest) (*ListReconFilesResponse, error)
	RemoveReconFile(context.Context, *RemoveReconFileRequest) (*RemoveReconFileResponse, error)
	// Bank statement rows: the fifth voice. Imported verbatim from the CSV
	// the bank portal exports, deduplicated by the bank's own reference, and
	// matched to payments — the match lives on the payment and is reversible;
	// the bank's row never changes.
	ImportBankStatement(context.Context, *ImportBankStatementRequest) (*ImportBankStatementResponse, error)
	ListBankTransactions(context.Context, *ListBankTransactionsRequest) (*ListBankTransactionsResponse, error)
	MatchBankTransaction(context.Context, *MatchBankTransactionRequest) (*MatchBankTransactionResponse, error)
	// 记下这笔钱是谁那条线上的（客户 / 供应商 / 退税 / 不用核销 / 待处理）。
	// 银行那一行本身一个字不改——归属是我们的判断，可改可撤。
	SetBankTransactionOwnership(context.Context, *SetBankTransactionOwnershipRequest) (*SetBankTransactionOwnershipResponse, error)
	UnmatchBankTransaction(context.Context, *UnmatchBankTransactionRequest) (*UnmatchBankTransactionResponse, error)
	// 手工登记一行流水。CSV 导入之外的另一条入口：银行还没出对账单、或者
	// 客户先发了水单，财务要先把这笔钱记下来。出口的收款对账原来自己有一张
	// 表干这件事，F2 之后由这里统一收着。
	RecordBankTransaction(context.Context, *RecordBankTransactionRequest) (*RecordBankTransactionResponse, error)
	// 银行给的那份对账单（PDF）。流水行是员工敲进来的数，对账单是凭证——
	// 两者对不上时说了算的是纸。一行一份，再传一次是替换。
	PresignBankTransactionFile(context.Context, *PresignBankTransactionFileRequest) (*PresignBankTransactionFileResponse, error)
	AttachBankTransactionFile(context.Context, *AttachBankTransactionFileRequest) (*AttachBankTransactionFileResponse, error)
	// 取单独一行。核销之前要拿到金额和币种才能判断能不能核，靠它。
	GetBankTransaction(context.Context, *GetBankTransactionRequest) (*GetBankTransactionResponse, error)
	// 我们自己的银行账户。跟着账本走：账本在这个服务里，账户清单也在这里，
	// 否则流水上的 account_id 指不到任何地方。
	ListBankAccounts(context.Context, *ListBankAccountsRequest) (*ListBankAccountsResponse, error)
	CreateBankAccount(context.Context, *CreateBankAccountRequest) (*CreateBankAccountResponse, error)
	// 记下这一行被认领了多少。客户那条线的核销记录在出口库，出口核完之后把
	// 结果写回来——账本自己算不出来，但账本必须知道，否则「还没处理完」那个
	// 队列就筛不准。
	SetBankTransactionClaim(context.Context, *SetBankTransactionClaimRequest) (*SetBankTransactionClaimResponse, error)
	mustEmbedUnimplementedPurchaseOrderServiceServer()
}

